    Bug 2042080 - Prevent stale connecting state from leaking across test files. r=jtracey


    Should fix intermittent comm/mail/components/accountcreation/test/browser/browser_oAuthGranularScopes.js | testNotGranted - OAuth telemetry should have been recorded - null != null

    If any prior test file starts an OAuth flow (setting gConnecting[oauth.test.test] = true) and ends before the flow completes normally (so finishAuthorizationRequest() is never called), gConnecting stayed true.

    Differential Revision: https://phabricator.services.mozilla.com/D303035

diff --git a/mailnews/base/src/OAuth2.sys.mjs b/mailnews/base/src/OAuth2.sys.mjs
index 3f31dcce820..b5b123d9d8d 100644
--- a/mailnews/base/src/OAuth2.sys.mjs
+++ b/mailnews/base/src/OAuth2.sys.mjs
@@ -521,11 +521,12 @@ OAuth2.prototype = {
 };

 /**
- * Reset the global cooldown state.
+ * Reset the global state variables.
  */
-OAuth2.clearCooldowns = function () {
-  log.debug("Clearing all OAuth cooldowns");
+OAuth2.clearState = function () {
+  log.debug("Clearing state");
   gCooldown.clear();
+  gConnecting.clear();
 };

 class InternalRequest {
diff --git a/mailnews/base/src/OAuth2Module.sys.mjs b/mailnews/base/src/OAuth2Module.sys.mjs
index 3a15ea88afb..a37d69bb614 100644
--- a/mailnews/base/src/OAuth2Module.sys.mjs
+++ b/mailnews/base/src/OAuth2Module.sys.mjs
@@ -494,7 +494,7 @@ OAuth2Module._forgetObjects = function () {
     }
   }
   oAuth2Objects.clear();
-  OAuth2.clearCooldowns();
+  OAuth2.clearState();
 };

